41	function wrapTextSvg(text, charsPerLine = 60) {
42	  const words = text.split(' ');
43	  const lines = [];
44	  let current = '';
45	  for (const w of words) {
46	    if (current.length + w.length + 1 > charsPerLine && current) {
47	      lines.push(current);
48	      current = w;
49	    } else {
50	      current = current ? current + ' ' + w : w;
51	    }
52	  }
53	  if (current) lines.push(current);
54	  return lines.length ? lines : [''];
55	}
56	
57	// ──────────────────────────────────────────────────────────────
58	// Localized legend strings (auto-derived per spec).
59	// Extended by adding a new `lang` key; missing keys fall back to 'ko'.
60	// ──────────────────────────────────────────────────────────────
61	const LEGEND = {
62	  ko: {
63	    required:       '필수 입력',
64	    dropdown:       '▼ 복수 선택',
65	    range:          '~ 범위(LOW~HIGH)',
66	    status_done:    '완료',
67	    status_partial: '부분입고',
68	    status_open:    '미입고',
69	    hotspot_text:   '밑줄 파랑',
70	    hotspot_label:  'Hotspot (더블클릭 이동)',
71	    editable_cell:  '노랑 셀',
72	    editable_label: '편집 가능',
73	  },
74	  en: {
75	    required:       'Required',
76	    dropdown:       '▼ Multi-select',
77	    range:          '~ Range (LOW~HIGH)',
78	    status_done:    'Done',
79	    status_partial: 'Partial',
80	    status_open:    'Open',
81	    hotspot_text:   'Blue underline',
82	    hotspot_label:  '= Hotspot (click to navigate)',
83	    editable_cell:  'Yellow cell',
84	    editable_label: '= Editable',
85	  },
86	  ja: {
87	    required:       '必須入力',
88	    dropdown:       '▼ 複数選択',
89	    range:          '~ 範囲(LOW~HIGH)',
90	    status_done:    '完了',
91	    status_partial: '一部入荷',
92	    status_open:    '未入荷',
93	    hotspot_text:   '青下線',
94	    hotspot_label:  '= Hotspot (ダブルクリックで遷移)',
95	    editable_cell:  '黄色セル',
96	    editable_label: '= 編集可能',
97	  },
98	};
99	function legendFor(lang) { return LEGEND[lang] || LEGEND.ko; }
100	
101	// Output scale factor — applied to the outer SVG width/height (and to the
102	// metrics helpers so the headless browser viewport matches). The viewBox
103	// stays at the original coordinate space so all internal positions/fonts are
104	// unchanged; the browser simply renders the same SVG content at 15% larger.
105	// Raise to make mockup PNGs bigger/crisper; lower if embedded images become
106	// too wide for the Inputs & Screens sheet.
107	const RENDER_SCALE = 1.15;
108	
109	// Approximate pixel width of a text string at 12 px font.
110	// Conservative estimate: ASCII ≈ 7 px, CJK/full-width ≈ 13 px.
111	// Used to lay out the selection-screen label column dynamically so that
112	// long English labels (e.g. "Distribution Channel (S_VTWEG)") don't run
113	// underneath the input boxes — the previous fixed inputX=200 truncated
114	// anything wider than 162 px.
115	function approxTextWidthPx(s) {
116	  let w = 0;
117	  for (const ch of String(s ?? '')) {
118	    w += (ch.charCodeAt(0) > 0x7F ? 13 : 7);
119	  }
120	  return w;
121	}
122	
123	/**
124	 * fields: [{
125	 *   required?: boolean,
126	 *   label: string,             e.g. '구매조직'
127	 *   name: string,              e.g. 'S_EKORG'
128	 *   range?: boolean,           true → LOW ~ HIGH two inputs
129	 *   note?: string,
130	 * }, ...]
131	 *
132	 * NOTE: `defaultLow` / `defaultHigh` are ACCEPTED in the field schema for
133	 *  spec documentation (they show up in the Parameters table), but they are
134	 *  NOT rendered inside the input-box graphic any more. The field name is
135	 *  already labeled next to the box; stuffing "BOM" / "1000" / "오늘" inside
136	 *  the input box just adds visual noise. Callers can still pass these
137	 *  values — the renderer silently ignores them.
138	 *
139	 * `lang` controls the bottom legend text ('ko' | 'en' | 'ja').
140	 */
141	export function renderSelectionScreenSVG({
142	  fields = [],
143	  blockLabel = '조회 조건',
144	  optionFields = [],
